import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        long n = readInt(reader);
        long m = readInt(reader);

        if (n > m) {
            long t = n;
            n = m;
            m = t;
        }

        long product = n * m;

        if (n == 1) {
            long[] penalty = {0, 1, 2, 3, 2, 1};
            product -= penalty[(int) (m % 6)];
        } else if (n == 2) {
            if (m == 2) {
                product -= 4;
            } else if (m == 3 || m == 7) {
                product -= 2;
            }
        } else if (n == 3) {
            product -= (m & 1L);
        } else if ((n & 1L) == 1L && (m & 1L) == 1L) {
            product -= 1;
        }

        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
        out.println(product);
        out.flush();
    }

    private static int readInt(BufferedReader in) throws IOException {
        int c;
        while ((c = in.read()) != -1 && c <= ' ') {
        }

        int sign = 1;
        if (c == '-' || c == '+') {
            if (c == '-') {
                sign = -1;
            }
            c = in.read();
        }

        int value = 0;
        while (c != -1 && c > ' ') {
            value = value * 10 + (c - '0');
            c = in.read();
        }

        return value * sign;
    }
}
